window.__POLYGON_SCRIPT_V2_PARTS__.push("      }\n\n      function closeDropdowns() {\n        [els.viewDropdown, els.menuDropdown].forEach(dropdown => dropdown.classList.remove('is-open'));\n        [els.viewButton, els.menuButton].forEach(button => button.setAttribute('aria-expanded', 'false'));\n      }\n\n      function applyLayer(name, enabled) {\n        state.layers[name] = enabled;\n        const classMap = {\n          grid: 'hide-grid',\n          labels: 'hide-labels',\n          routes: 'hide-routes',\n          cover: 'show-cover'\n        };\n        if (name === 'cover') {\n          els.mapViewport.classList.toggle(classMap[name], enabled);\n          if (enabled) toast('Слой укрытий показан демонстрационно');\n        } else {\n          els.mapViewport.classList.toggle(classMap[name], !enabled);\n        }\n      }\n\n      function resetLayout() {\n        state.leftWidth = 372;\n        state.rightWidth = 336;\n        togglePanel('left', false);\n        togglePanel('right', false);\n        applyPanelWidths();\n        safeStorageRemove('polygonPrototype.leftWidth');\n        safeStorageRemove('polygonPrototype.rightWidth');\n        toast('Расположение панелей сброшено');\n      }\n\n      function refreshUnitSurfaces(options = {}) {\n        const keepModal = options.keepModal && state.modalType === 'unit-details';\n        renderUnits();\n        renderInspector();\n        if (state.workspace === 'unit-editor') renderWorkspace();\n        if (keepModal) renderUnitDetailsModal();\n      }\n\n      function updateUnitField(field, rawValue, options = {}) {\n        const unit = ensureUnitDefaults(selectedUnit());\n        if (!unit) return;\n        const numeric = ['health','suppression','fatigue','morale','awarenessSeconds','loadedAmmo','reserveAmmo','x','y','heading'];\n        let value = numeric.includes(field) ? Number(rawValue) : rawValue;\n        if (numeric.includes(field) && !Number.isFinite(value)) value = 0;\n        if (['health','suppression','fatigue','morale'].includes(field)) value = Math.max(0, Math.min(100, value));\n        if (field === 'awarenessSeconds') value = Math.max(0, Math.min(120, value));\n        if (field === 'side') {\n          unit.side = value;\n          unit.sideLabel = value === 'red' ? 'Красные' : value === 'neutral' ? 'Нейтральные' : 'Синие';\n        } else if (field === 'archetype') {\n          applyArchetypeProfiles(unit, value);\n        } else {\n          unit[field] = value;\n        }\n        unit.ammo = Number(unit.loadedAmmo || 0) + Number(unit.reserveAmmo || 0);\n        if (field === 'name') unit.short = unit.name.trim().split(/\\s+/).map(part => part[0]).join('').slice(0,2).toUpperCase() || 'Ю';\n        refreshUnitSurfaces({ keepModal: options.keepModal });\n      }\n\n      function copySelectedUnit() {\n        const source = ensureUnitDefaults(selectedUnit());\n        if (!source) return;\n        const copy = JSON.parse(JSON.stringify(source));\n        copy.id = `unit-${Date.now()}`;\n        copy.name = `${source.name} — копия`;\n        copy.short = `${source.short}К`.slice(0,2);\n        copy.x = Math.min(96, source.x + 3);\n        copy.y = Math.min(96, source.y + 3);\n        state.units.push(copy);\n        state.selectedUnitId = copy.id;\n        state.unitListOpen = false;\n        refreshUnitSurfaces({ keepModal: state.modalType === 'unit-details' });\n        toast('Создана копия юнита');\n      }\n\n      function deleteSelectedUnit() {\n        const unit = selectedUnit();\n        if (!unit) return;\n        if (!confirm(`Удалить юнита «${unit.name}»?`)) return;\n        state.units = state.units.filter(item => item.id !== unit.id);\n        state.selectedUnitId = null;\n        state.unitListOpen = false;\n        if (state.modalType === 'unit-details') closeModal();\n        refreshUnitSurfaces();\n        toast('Юнит удалён');\n      }\n\n      function handleUnitAction(action) {\n        const unit = ensureUnitDefaults(selectedUnit());\n        if (action === 'toggle-list') { state.unitListOpen = !state.unitListOpen; renderWorkspace(); return; }\n        if (action === 'close-list') { state.unitListOpen = false; renderWorkspace(); return; }\n        if (action === 'open-details' && unit) { state.unitDetailsTab = 'basic'; openModal('unit-details'); return; }\n        if (!unit) return;\n        if (action === 'locate') {\n          const marker = els.unitLayer.querySelector(`[data-unit-id=\"${CSS.escape(unit.id)}\"]`);\n          marker?.animate([{transform:'translate(-50%,-50%) scale(1)'},{transform:'translate(-50%,-50%) scale(1.35)'},{transform:'translate(-50%,-50%) scale(1)'}], {duration:650});\n          toast('Юнит подсвечен на карте');\n        }\n        if (action === 'move') { closeModal(); setMapAction('move-selected-unit', 'Укажите новое положение юнита'); }\n        if (action === 'rotate') { closeModal(); setMapAction('rotate-selected-unit', 'Укажите направление юнита'); }\n        if (action === 'copy') copySelectedUnit();\n        if (action === 'delete') deleteSelectedUnit();\n      }\n\n      function handleWorkspaceClick(event) {\n        const unitActionButton = event.target.closest('[data-unit-action]');\n        if (unitActionButton) { handleUnitAction(unitActionButton.dataset.unitAction); return; }\n        const poseButton = event.target.closest('[data-unit-pose]');\n        if (poseButton) { const unit = ensureUnitDefaults(selectedUnit()); if (unit) { unit.pose = poseButton.dataset.unitPose; refreshUnitSurfaces({ keepModal: state.modalType === 'unit-details' }); } return; }\n        const workspaceButton = event.target.closest('[data-workspace]');\n        if (workspaceButton) {\n          setWorkspaceMode(workspaceButton.dataset.workspace);\n          return;\n        }\n        const submodeButton = event.target.closest('[data-map-submode]');\n        if (submodeButton) {\n          state.mapSubmode = submodeButton.dataset.mapSubmode;\n          renderWorkspace();\n          return;\n        }\n        const mapActionButton = event.target.closest('[data-map-action]');\n        if (mapActionButton) {\n          const action = mapActionButton.dataset.mapAction;\n          const labels = {\n            'add-point': 'Укажите точку на карте',\n            'add-area': 'Укажите центр области на карте',\n            'add-target': 'Укажите цель на карте',\n            'place-unit': 'Укажите место размещения юнита',\n            'move-selected-unit': 'Укажите новое положение юнита',\n            'rotate-selected-unit': 'Укажите направление юнита'\n          };\n          setMapAction(action, labels[action] || `Укажите место: ${mapSubmodeNames[state.mapSubmode]}`);\n          return;\n        }\n        const unitButton = event.target.closest('[data-select-unit]');\n        if (unitButton) {\n          state.unitListOpen = false;\n          selectUnit(unitButton.dataset.selectUnit);\n          return;\n        }\n        const actionButton = event.target.closest('[data-action]');\n        if (!actionButton) return;\n        const action = actionButton.dataset.action;\n        if (action === 'add-track') toast('Структура дорожки будет проработана отдельно');\n        if (action === 'apply-map-size') toast('Размер поля применён только визуально в прототипе');\n        if (action === 'create-unit') {\n          setMapAction('place-unit', 'Укажите место размещения нового юнита');\n          toast('После размещения откроется редактор нового юнита');\n        }\n      }\n\n      function bindEvents() {\n        els.workspaceTabs.addEventListener('click', handleWorkspaceClick);\n        els.leftPanelContent.addEventListener('click', handleWorkspaceClick);\n        els.leftPanelContent.addEventListener('input', event => {\n          const search = event.target.closest('[data-unit-search]');\n          if (search) { state.unitSearch = search.value; const position = search.selectionStart; renderWorkspace(); const next = els.leftPanelContent.querySelector('[data-unit-search]'); if (next) { next.focus(); next.setSelectionRange(position, position); } return; }\n          const field = event.target.closest('[data-unit-field]');\n          if (field && field.dataset.unitField === 'name') updateUnitField(field.dataset.unitField, field.value);\n        });\n        els.leftPanelContent.addEventListener('change', event => {\n          const field = event.target.closest('[data-unit-field]');\n          if (field) updateUnitField(field.dataset.unitField, field.value);\n        });\n        els.inspectorTabs.addEventListener('click', event => {\n          const button = event.target.closest('[data-inspector]');\n          if (button) setInspectorTab(button.dataset.inspector);\n        });\n\n        els.unitLayer.addEventListener('click', event => {\n          const button = event.target.closest('[data-unit-id]');\n          if (button) {\n            event.stopPropagation();\n            selectUnit(button.dataset.unitId);\n          }\n        });\n        els.unitLayer.addEventListener('contextmenu', event => {\n          const button = event.target.closest('[data-unit-id]');\n          if (!button) return;\n          event.preventDefault();\n          event.stopPropagation();\n          selectUnit(button.dataset.unitId, { silent: true });\n          state.contextUnitId = button.dataset.unitId;\n          els.contextMenu.innerHTML = `<div class=\"context-menu__title\">${escapeHtml(selectedUnit().name)}</div>\n            <button type=\"button\" data-unit-context-action=\"edit\"><span class=\"context-menu__icon\">✎</span>Редактировать юнита</button>\n            <button type=\"button\" data-unit-context-action=\"move\"><span class=\"context-menu__icon\">↔</span>Переместить</button>\n            <button type=\"button\" data-unit-context-action=\"rotate\"><span class=\"context-menu__icon\">↻</span>Повернуть</button>\n            <button type=\"button\" data-unit-context-action=\"copy\"><span class=\"context-menu__icon\">▣</span>Копировать</button>\n            <button type=\"button\" data-unit-context-action=\"delete\"><span class=\"context-menu__icon\">×</span>Удалить</button>`;\n");
